CustomField.formula:
IF( ISPICKVAL(TSGCFG__Consolidation_Method__c, 'Average') && TSGCFG__TotalCPCLineItems__c > 0,
    TSGCFG__SumofCPCBW__c/  TSGCFG__TotalCPCLineItems__c,
    IF(ABS(TSGCFG__TotalBWVolume__c - TSGCFG__Total_Volume_Includes_B_W__c )<>0, TSGCFG__TotalBWMonthlyCost__c / ABS(TSGCFG__TotalBWVolume__c - TSGCFG__Total_Volume_Includes_B_W__c ),
        IF(TSGCFG__TotalCPCLineItems__c > 0,  TSGCFG__SumofCPCBW__c/  TSGCFG__TotalCPCLineItems__c , 0)
       )
   )



/*NOT IN USE 
 IF( ISPICKVAL(TSGCFG__Consolidation_Method__c, 'Average') && TSGCFG__TotalCPCLineItems__c > 0,
